/* Refined Underline for Better UI Readability & Web Font Integration */
a {
  text-decoration: underline;
  text-underline-offset: 0.2em; /* Lifts the underline to avoid descenders */
  text-decoration-thickness: 1px; /* Thins the underline for elegance */
  text-decoration-color: #007bff; /* Custom color for brand consistency */
  /* Consider text-decoration-skip-ink: none; if you want a continuous line */
}

/* Example with hover effect */
a:hover {
  text-decoration-thickness: 2px; /* Slight thickening on hover */
  text-decoration-color: #0056b3;
}
